  /// Kotlin `getSystemPrompt(type, intensity)` birebir aynı dizeyi döndürür.
  String getSystemPrompt(PersonalityType type, double intensity, {String? customPrompt}) {
    if ((customPrompt ?? '').trim().isNotEmpty) return customPrompt!.trim();
    return _basePrompt;
  }

